function run_fir_mode_a_analysis(repositoryRoot)
T=readtable(fullfile(repositoryRoot,"data","processed","fir_mode_a_esp32c6_observations.csv"),TextType="string");assert(height(T)==2400);out=fullfile(repositoryRoot,"artifacts","matlab","fir_mode_a");if ~isfolder(out),mkdir(out);end
L=["c_cpp","rust","micropython"];N=[0 16 32 64 128 256 512 1024];M=zeros(8,3);S=table();
for a=1:3,for b=1:8,x=T.normalized_time_per_call_us(T.language==L(a)&T.input_samples==N(b));assert(numel(x)==100);M(b,a)=median(x);S=[S;table(L(a),N(b),mean(x),median(x),std(x),min(x),max(x),'VariableNames',{'language','input_samples','mean_us','median_us','std_us','min_us','max_us'})];end,end
writetable(S,fullfile(out,"fir_mode_a_summary.csv"));R=M./M(:,1);writetable(table(repmat(N',3,1),repelem(L',8),reshape(R,[],1),'VariableNames',{'input_samples','language','ratio_to_cpp'}),fullfile(out,'fir_mode_a_ratios.csv'));
f=figure('Visible','off');semilogy(N,M,'-o','LineWidth',1.5);grid on;legend('C++','Rust','MicroPython');xlabel('Input samples');ylabel('Time per call (us)');title('ESP32-C6 Mode A FIR');exportgraphics(f,fullfile(out,'figure1_fir_execution_time.png'),'Resolution',300);exportgraphics(f,fullfile(out,'figure1_fir_execution_time.pdf'),'ContentType','vector');savefig(f,fullfile(out,'figure1_fir_execution_time.fig'));close(f);
f=figure('Visible','off');semilogy(N,R,'-o','LineWidth',1.5);grid on;legend('C++','Rust','MicroPython');xlabel('Input samples');ylabel('Median / C++');title('FIR normalized to C++');exportgraphics(f,fullfile(out,'figure2_fir_normalized_to_cpp.png'),'Resolution',300);exportgraphics(f,fullfile(out,'figure2_fir_normalized_to_cpp.pdf'),'ContentType','vector');savefig(f,fullfile(out,'figure2_fir_normalized_to_cpp.fig'));close(f);
H=readtable(fullfile(repositoryRoot,"data","processed","plauska_fir_historical_summary.csv"),TextType="string");assert(height(H)==24);HM=zeros(8,3);for a=1:3,for b=1:8,HM(b,a)=H.mean_us(H.language==L(a)&H.input_samples==N(b));end,end
f=figure('Visible','off');t=tiledlayout(1,2);nexttile;semilogy(N,HM,'-o');grid on;title('Plauska historical ESP32 Xtensa');xlabel('Input samples');ylabel('Mean time (us)');nexttile;semilogy(N,M,'-o');grid on;title('This study ESP32-C6 Mode A');xlabel('Input samples');title(t,'Descriptive context; protocols/platforms differ');exportgraphics(f,fullfile(out,'figure3_fir_historical_context.png'),'Resolution',300);exportgraphics(f,fullfile(out,'figure3_fir_historical_context.pdf'),'ContentType','vector');savefig(f,fullfile(out,'figure3_fir_historical_context.fig'));close(f);fprintf('FIR_MATLAB_PASS\n');
end
